INSERT INTO topics (
  category_id, title, difficulty, duration_min, duration_max, guide_text, is_recommended, sort_order
) VALUES (
  #{categoryId}, #{title}, #{difficulty}, #{durationMin}, #{durationMax},
  #{guide}, #{recommended}, #{sortOrder}
)

mapper.select:
SELECT s.session_id AS id, u.login_name, u.nickname, t.title, s.status, DATE_FORMAT(s.started_at, '%Y-%m-%d %H:%i') AS started_at, DATE_FORMAT(s.ended_at, '%Y-%m-%d %H:%i') AS ended_at, s.duration_seconds, r.report_id, r.total_score AS score FROM training_sessions s INNER JOIN users u ON u.user_id = s.user_id INNER JOIN topics t ON t.topic_id = s.topic_id LEFT JOIN analysis_reports r ON r.session_id = s.session_id
AND s.status = #{status}
ORDER BY s.session_id DESC LIMIT 200

SELECT mime_type, audio_data
FROM session_audios
WHERE session_id = #{id}

SELECT f.feedback_id AS id, u.login_name, u.nickname, f.category, f.content, f.status, DATE_FORMAT(f.created_at, '%Y-%m-%d %H:%i') AS created_at, f.reply_content AS reply, DATE_FORMAT(f.replied_at, '%Y-%m-%d %H:%i') AS replied_at FROM user_feedbacks f INNER JOIN users u ON u.user_id = f.user_id
AND f.status = #{status}
ORDER BY f.feedback_id DESC

mapper.update:
UPDATE user_feedbacks
SET status = #{status},
    reply_content = #{reply},
    replied_at = #{repliedAt}
WHERE feedback_id = #{id}
